1	//! Explicit single-output native session. Recovery and multi-output are future work.
2	use crate::{Fluxwm, scene::RuntimeScene};
3	use flux_native::system::{Driver, NativeEvent};
4	use smithay::{
5	    backend::renderer::damage::OutputDamageTracker,
6	    output::{Mode, Output, PhysicalProperties, Subpixel},
7	    reexports::{
8	        calloop::{
9	            EventLoop, LoopHandle, RegistrationToken,
10	            ping::make_ping,
11	            timer::{TimeoutAction, Timer},
12	        },
13	        wayland_server::backend::GlobalId,
14	    },
15	    utils::Transform,
16	};
17	use std::{cell::RefCell, rc::Rc, time::Duration};
18	
19	struct PresentedScene {
20	    scene: Rc<RuntimeScene>,
21	    cursor_surface: Option<smithay::reexports::wayland_server::protocol::wl_surface::WlSurface>,
22	}
23	
24	struct Context {
25	    driver: Driver<Fluxwm>,
26	    device: u64,
27	    output: Output,
28	    global: Option<GlobalId>,
29	    damage: OutputDamageTracker,
30	    stopped: bool,
31	    watchdog: Option<RegistrationToken>,
32	    handle: Box<dyn Fn() -> Option<LoopHandle<'static, Fluxwm>>>,
33	}
34	pub struct Handle(Rc<RefCell<Context>>);
35	impl Handle {
36	    pub fn shutdown(&mut self, state: &mut Fluxwm) {
37	        self.0.borrow_mut().shutdown(state);
38	    }
39	}
40	impl Drop for Handle {
41	    fn drop(&mut self) {
42	        // Also run on startup errors, while the loop and its registrations live.
43	        let mut context = self.0.borrow_mut();
44	        context.driver.stop();
45	        if context.driver.output_cleanup_failures() != 0 || context.driver.close_failures() != 0 {
46	            tracing::error!(
47	                "native shutdown could not conclusively restore and retire all resources"
48	            );
49	        }
50	    }
51	}
52	impl Context {
53	    fn cancel_watchdog(&mut self) {
54	        if let Some(token) = self.watchdog.take()
55	            && let Some(handle) = (self.handle)()
56	        {
57	            handle.remove(token);
58	        }
59	    }
60	    fn shutdown(&mut self, state: &mut Fluxwm) {
61	        if self.stopped {
62	            return;
63	        }
64	        self.stopped = true;
65	        self.cancel_watchdog();
66	        state.scene = None;
67	        state.pointer_focus_dirty = true;
68	        state.render_suspended = true;
69	        state.host_focus_changed(false);
70	        state.space.unmap_output(&self.output);
71	        if let Some(global) = self.global.take() {
72	            state.display_handle.remove_global::<Fluxwm>(global);
73	        }
74	        self.driver.stop();
75	        if self.driver.output_cleanup_failures() != 0 || self.driver.close_failures() != 0 {
76	            state.fail("native shutdown failed to restore or close resources".into());
77	        }
78	    }
79	    fn fail(&mut self, state: &mut Fluxwm, error: String) {
80	        self.shutdown(state);
81	        state.fail(error);
82	    }
83	    fn draw(&mut self, state: &mut Fluxwm) {
84	        if self.stopped || state.stopping || !state.dirty || state.render_suspended {
85	            return;
86	        }
87	        let Some(info) = self.driver.output_preview_info(self.device) else {
88	            self.fail(state, "native output disappeared".into());
89	            return;
90	        };
91	        if info.queue.pending_cookie.is_some() {
92	            return;
93	        }
94	        state.stats.redraws += 1;
95	        let damage = &mut self.damage;
96	        let result = self
97	            .driver
98	            .render_output_frame(self.device, |renderer, target, size| {
99	                let scene = Rc::new(
100	                    RuntimeScene::capture(
101	                        state,
102	                        flux_core::Rect {
103	                            x: 0.,
104	                            y: 0.,
105	                            width: f64::from(size.w),
106	                            height: f64::from(size.h),
107	                        },
108	                    )
109	                    .map_err(|e| e.to_string())?,
110	                );
111	                let elements = scene.render_elements(renderer).map_err(|e| e.to_string())?;
112	                let result = damage
113	                    .render_output(renderer, target, 0, &elements, [0.06, 0.07, 0.09, 1.])
114	                    .map_err(|e| e.to_string())?;
115	                let cursor_sync = crate::cursor::paint(
116	                    renderer,
117	                    target,
118	                    size,
119	                    &state.cursor_image,
120	                    state
121	                        .seat
122	                        .get_pointer()
123	                        .map(|p| p.current_location())
124	                        .unwrap_or_default(),
125	                )?;
126	                let cursor_surface = if cursor_sync.is_some() {
127	                    if let smithay::input::pointer::CursorImageStatus::Surface(surface) =
128	                        &state.cursor_image
129	                    {
130	                        Some(surface.clone())
131	                    } else {
132	                        None
133	                    }
134	                } else {
135	                    None
136	                };
137	                let sync = cursor_sync.unwrap_or(result.sync);
138	                Ok((
139	                    Rc::new(PresentedScene {
140	                        scene,
141	                        cursor_surface,
142	                    }),
143	                    sync,
144	                ))
145	            });
146	        if let Err(error) = result {
147	            self.fail(state, error.to_string());
148	            return;
149	        }
150	        state.dirty = false;
151	        state.stats.compositions += 1;
152	        state.stats.submissions += 1;
153	        let Some(cookie) = self
154	            .driver
155	            .output_preview_info(self.device)
156	            .and_then(|i| i.queue.pending_cookie)
157	        else {
158	            self.fail(state, "native submission has no completion cookie".into());
159	            return;
160	        };
161	        let _ = cookie;
162	    }
163	}
164	
165	// The callback owner installs the watchdog without borrowing the context twice.
166	fn draw(context: &Rc<RefCell<Context>>, handle: &LoopHandle<'static, Fluxwm>, state: &mut Fluxwm) {
167	    let before = context
168	        .borrow()
169	        .driver
170	        .output_preview_info(context.borrow().device)
171	        .and_then(|i| i.queue.pending_cookie);
172	    context.borrow_mut().draw(state);
173	    let after = context
174	        .borrow()
175	        .driver
176	        .output_preview_info(context.borrow().device)
177	        .and_then(|i| i.queue.pending_cookie);
178	    if before == after {
179	        return;
180	    }
181	    if let Some(cookie) = after {
182	        let weak = Rc::downgrade(context);
183	        match handle.insert_source(
184	            Timer::from_duration(Duration::from_secs(2)),
185	            move |_, _, state| {
186	                if let Some(context) = weak.upgrade() {
187	                    let mut context = context.borrow_mut();
188	                    context.watchdog = None;
189	                    if !context.stopped
190	                        && context
191	                            .driver
192	                            .output_preview_info(context.device)
193	                            .is_some_and(|i| i.queue.pending_cookie == Some(cookie))
194	                    {
195	                        context.fail(state, "native page flip timed out; session stopped".into());
196	                    }
197	                }
198	                TimeoutAction::Drop
199	            },
200	        ) {
201	            Ok(token) => context.borrow_mut().watchdog = Some(token),
202	            Err(error) => context
203	                .borrow_mut()
204	                .fail(state, format!("native frame timer: {error}")),
205	        }
206	    }
207	}
208	
209	pub fn init(
210	    event_loop: &mut EventLoop<'static, Fluxwm>,
211	    state: &mut Fluxwm,
212	    device: u64,
213	    connector: u32,
214	) -> Result<Handle, Box<dyn std::error::Error>> {
215	    let slot: Rc<RefCell<std::rc::Weak<RefCell<Context>>>> = Rc::default();
216	    let notify_slot = slot.clone();
217	    let init_failure: Rc<RefCell<Option<String>>> = Rc::default();
218	    let notify_failure = init_failure.clone();
219	    let mut driver = Driver::new(&event_loop.handle(), state, move |event, state| {
220	        let Some(context) = notify_slot.borrow().upgrade() else {
221	            // Driver initialization reports GPU/session events synchronously.
222	            match event {
223	                NativeEvent::Failure {
224	                    device: failed_device,
225	                    error,
226	                } if failed_device.is_none() || failed_device == Some(device) => {
227	                    *notify_failure.borrow_mut() =
228	                        Some(format!("native initialization: {error:?}"));
229	                }
230	                NativeEvent::SessionActive(false) => {
231	                    *notify_failure.borrow_mut() = Some("native seat is inactive".into());
232	                }
233	                NativeEvent::Failure { error, .. } => {
234	                    tracing::warn!(?error, "unselected native GPU initialization")
235	                }
236	                _ => (),
237	            }
238	            return;
239	        };
240	        let mut context = context.borrow_mut();
241	        if context.stopped || state.stopping {
242	            return;
243	        }
244	        match event {
245	            NativeEvent::Input(event) => state.process_input_event(event),
246	            NativeEvent::PageFlip { device, .. } if device == context.device => {
247	                let Some(info) = context.driver.output_preview_info(device) else {
248	                    context.fail(state, "native output disappeared".into());
249	                    return;
250	                };
251	                if info.queue.faulted || info.queue.closed || !info.queue.active {
252	                    context.fail(state, "native output completion failed".into());
253	                    return;
254	                }
255	                if info.queue.pending_cookie.is_none() {
256	                    context.cancel_watchdog();
257	                }
258	                let content = context.driver.output_content::<PresentedScene>(device);
259	                let scene = content.as_ref().map(|content| content.scene.clone());
260	                let changed = match (&state.scene, &scene) {
261	                    (Some(old), Some(new)) => !Rc::ptr_eq(old, new),
262	                    (None, Some(_)) | (Some(_), None) => true,
263	                    _ => false,
264	                };
265	                if changed {
266	                    state.scene = scene;
267	                    state.pointer_focus_dirty = true;
268	                    if let Some(surface) = content
269	                        .as_ref()
270	                        .and_then(|content| content.cursor_surface.as_ref())
271	                    {
272	                        smithay::desktop::utils::send_frames_surface_tree(
273	                            surface,
274	                            &context.output,
275	                            state.start_time.elapsed(),
276	                            Some(Duration::ZERO),
277	                            |_, _| Some(context.output.clone()),
278	                        );
279	                    }
280	                    if let Some(scene) = &state.scene {
281	                        for id in scene.windows() {
282	                            if let Some(item) = state.windows.get(id) {
283	                                item.window.send_frame(
284	                                    &context.output,
285	                                    state.start_time.elapsed(),
286	                                    Some(Duration::ZERO),
287	                                    |_, _| Some(context.output.clone()),
288	                                );
289	                                state.stats.frames_sent += 1;
290	                            }
291	                        }
292	                    }
293	                }
294	                if state.dirty {
295	                    state.request_redraw();
296	                }
297	            }
298	            NativeEvent::SessionActive(false) => context.fail(
299	                state,
300	                "native seat paused; recovery is not implemented".into(),
301	            ),
302	            NativeEvent::GpuRemoved(id) if id == context.device => {
303	                context.fail(state, "native GPU removed".into())
304	            }
305	            NativeEvent::GpuReady(info) if info.device == context.device.to_string() => {
306	                context.fail(state, "native output topology changed".into())
307	            }
308	            NativeEvent::Failure { device, error }
309	                if device.is_none() || device == Some(context.device) =>
310	            {
311	                context.fail(state, format!("native backend: {error:?}"))
312	            }
313	            _ => (),
314	        }
315	    })?;
316	    if let Some(error) = init_failure.borrow_mut().take() {
317	        return Err(error.into());
318	    }
319	    let assignment = driver
320	        .gpu_info()
321	        .into_iter()
322	        .find(|g| g.device == device.to_string())
323	        .and_then(|g| g.output_plan)
324	        .and_then(|p| p.assignments.into_iter().find(|a| a.connector == connector))
325	        .ok_or("requested native output is not available in the prepared output plan")?;
326	    let bootstrap = driver.begin_output_preview(device, connector, [15, 18, 23, 255])?;
327	    if bootstrap.last_failure.is_some()
328	        || bootstrap.queue.pending_cookie.is_some()
329	        || bootstrap.queue.front_cookie.is_none()
330	        || bootstrap.queue.faulted
331	        || !bootstrap.queue.active
332	    {
333	        return Err("native output bootstrap did not complete conclusively".into());
334	    }
335	    let size = (
336	        i32::from(assignment.mode.width),
337	        i32::from(assignment.mode.height),
338	    )
339	        .into();
340	    let mode = Mode {
341	        size,
342	        refresh: i32::try_from(assignment.refresh_millihz)?,
343	    };
344	    let output = Output::new(
345	        format!("drm-{device}-{connector}"),
346	        PhysicalProperties {
347	            size: (0, 0).into(),
348	            subpixel: Subpixel::Unknown,
349	            make: "FluxWM".into(),
350	            model: "DRM".into(),
351	            serial_number: String::new(),
352	        },
353	    );
354	    let global = output.create_global::<Fluxwm>(&state.display_handle);
355	    output.change_current_state(
356	        Some(mode),
357	        Some(Transform::Normal),
358	        None,
359	        Some((0, 0).into()),
360	    );
361	    output.set_preferred(mode);
362	    state.space.map_output(&output, (0, 0));
363	    state.layout.set_viewport(flux_core::Size {
364	        width: f64::from(size.w),
365	        height: f64::from(size.h),
366	    })?;
367	    let context = Rc::new(RefCell::new(Context {
368	        driver,
369	        device,
370	        output,
371	        global: Some(global),
372	        damage: OutputDamageTracker::new(size, 1., Transform::Normal),
373	        stopped: false,
374	        watchdog: None,
375	        handle: {
376	            let weak = event_loop.handle().downgrade();
377	            Box::new(move || weak.upgrade())
378	        },
379	    }));
380	    *slot.borrow_mut() = Rc::downgrade(&context);
381	    let guard = Handle(context.clone());
382	    let (ping, source) = make_ping()?;
383	    state.redraw_ping = Some(ping);
384	    let weak_loop = event_loop.handle().downgrade();
385	    event_loop
386	        .handle()
387	        .insert_source(source, move |(), _, state| {
388	            if let Some(handle) = weak_loop.upgrade() {
389	                draw(&context, &handle, state);
390	            }
391	        })
392	        .map_err(|e| std::io::Error::other(e.to_string()))?;
393	    state.backend = "native";
394	    state.host_focus_changed(true);
395	    state.request_redraw();
396	    Ok(guard)
397	}
