316	/// Sources capture weak ownership. The independent session dispatcher outlives
317	/// input/GPU cleanup, including errors during partial initialization.
318	pub struct Driver<D: 'static> {
319	    kernel: Rc<RefCell<Kernel<D>>>,
320	    tokens: Vec<Registration>,
321	    _session_owner: Rc<Dispatcher<'static, LibSeatSessionNotifier, D>>,
322	}
323	impl<D: 'static> Driver<D> {
324	    pub fn new(
325	        handle: &LoopHandle<'static, D>,
326	        data: &mut D,
327	        notify: impl Fn(NativeEvent, &mut D) + 'static,
328	    ) -> Result<Self, Failure> {
329	        let (session, notifier) = LibSeatSession::new().map_err(|e| Failure {
330	            stage: Stage::SeatOpen,
331	            errno: e.as_errno(),
332	        })?;
333	        let notify: Notify<D> = Rc::new(notify);
334	        let weak_loop = handle.downgrade();
335	        let weak_handle: WeakHandle<D> = Rc::new(move || weak_loop.upgrade());
336	        let kernel = Rc::new(RefCell::new(Kernel {
337	            model: Lifecycle::default(),
338	            session: session.clone(),
339	            paths: BTreeMap::new(),
340	            gpus: BTreeMap::new(),
341	            input: None,
342	            input_token: None,
343	            handle: weak_handle.clone(),
344	            notify: notify.clone(),
345	            close_failures: Rc::new(Cell::new(0)),
346	            seat_owner: None,
347	            frame_pool: crate::frames::FramePool::default(),
348	            output_cleanup_failures: 0,
349	        }));
350	        let weak = Rc::downgrade(&kernel);
351	        let owner = Rc::new(Dispatcher::new(notifier, move |event, _, data: &mut D| {
352	            let Some(kernel) = weak.upgrade() else { return };
353	            let events = match event {
354	                SessionEvent::PauseSession => kernel.borrow_mut().pause(),
355	                SessionEvent::ActivateSession => {
356	                    kernel.borrow_mut().activate(&Rc::downgrade(&kernel))
357	                }
358	            };
359	            let notify = kernel.borrow().notify.clone();
360	            dispatch_events(
361	                events,
362	                |event| notify(event, data),
363	                || !kernel.borrow().model.closed(),
364	            );
365	        }));
366	        kernel.borrow_mut().seat_owner = Some(owner.clone());
367	        let mut driver = Self {
368	            kernel,
369	            tokens: vec![],
370	            _session_owner: owner,
371	        };
372	        let token = handle
373	            .register_dispatcher((*driver._session_owner).clone())
374	            .map_err(|_| Failure::at(Stage::SourceRegistration))?;
375	        driver
376	            .tokens
377	            .push(Registration::new(weak_handle.clone(), token));
378	        let udev = UdevBackend::new(session.seat()).map_err(|e| Failure {
379	            stage: Stage::UdevMonitor,
380	            errno: e.raw_os_error(),
381	        })?;
382	        let initial: Vec<_> = udev
383	            .device_list()
384	            .map(|(id, path)| UdevEvent::Added {
385	                device_id: id,
386	                path: path.to_owned(),
387	            })
388	            .collect();
389	        let weak = Rc::downgrade(&driver.kernel);
390	        let token = handle
391	            .insert_source(udev, move |event, _, data| {
392	                let Some(kernel) = weak.upgrade() else { return };
393	                let events = kernel.borrow_mut().udev(event, &Rc::downgrade(&kernel));
394	                let notify = kernel.borrow().notify.clone();
395	                dispatch_events(
396	                    events,
397	                    |event| notify(event, data),
398	                    || !kernel.borrow().model.closed(),
399	                );
400	            })
401	            .map_err(|_| Failure::at(Stage::SourceRegistration))?;
402	        driver
403	            .tokens
404	            .push(Registration::new(weak_handle.clone(), token));
405	        for event in initial {
406	            let events = driver
407	                .kernel
408	                .borrow_mut()
409	                .udev(event, &Rc::downgrade(&driver.kernel));
410	            for event in events {
411	                notify(event, data);
412	            }
413	        }
414	        if session.is_active() {
415	            let events = driver
416	                .kernel
417	                .borrow_mut()
418	                .activate(&Rc::downgrade(&driver.kernel));
419	            for event in events {
420	                notify(event, data);
421	            }
422	        }
423	        Ok(driver)
424	    }
