465	    /// Explicit physical modeset for one connector, also used by the manual probe.
466	    /// Exactly one preview per GPU is admitted; combined output transactions
467	    /// need coordinated rollback. Inspect last_failure even on an Ok result:
468	    /// uncertain submission stays owned until explicit restoration.
469	    pub fn begin_output_preview(
470	        &mut self,
471	        device: u64,
472	        connector: u32,
473	        color: [u8; 4],
474	    ) -> Result<PreviewInfo, PreviewFailure> {
475	        let mut kernel = self.kernel.borrow_mut();
476	        let pool = kernel.frame_pool.clone();
477	        let ready = kernel
478	            .gpus
479	            .get(&device)
480	            .is_some_and(|g| kernel.model.is_ready(g.ticket) && g.info.event_transport_healthy);
481	        if !ready {
482	            return Err(PreviewFailure::at(PreviewStage::Inactive));
483	        }
484	        let gpu = kernel.gpus.get_mut(&device).expect("ready GPU owned");
485	        if gpu.output.is_some() {
486	            return Err(PreviewFailure::at(PreviewStage::Busy));
487	        }
488	        let assignment = gpu
489	            .info
490	            .output_plan
491	            .as_ref()
492	            .and_then(|p| p.assignments.iter().find(|a| a.connector == connector))
493	            .cloned()
494	            .ok_or_else(|| PreviewFailure::at(PreviewStage::Prepare))?;
495	        gpu.output_epoch = gpu
496	            .output_epoch
497	            .checked_add(1)
498	            .ok_or_else(|| PreviewFailure::at(PreviewStage::Admission))?;
499	        let mut context = scanout::Context {
500	            drm: &gpu.drm,
501	            gbm: &gpu._gbm,
502	            renderer: &mut gpu._renderer,
503	            modes: &gpu._output_modes,
504	            seat: gpu._seat_device.clone(),
505	            pool: &pool,
506	            ticket: gpu.ticket,
507	        };
508	        let mut failure = PreviewFailure::at(PreviewStage::Prepare);
509	        for format in crate::target::formats(&assignment)
510	            .into_iter()
511	            .take(crate::target::MAX_TEST_ATTEMPTS)
512	        {
513	            match scanout::Output::begin(
514	                &mut context,
515	                assignment.clone(),
516	                format,
517	                gpu.output_epoch,
518	                color,
519	            ) {
520	                Ok(output) => {
521	                    let info = output.info();
522	                    gpu.output = Some(output);
523	                    return Ok(info);
524	                }
525	                Err(error) => {
526	                    if !matches!(error.stage, PreviewStage::Prepare | PreviewStage::Test) {
527	                        return Err(error);
528	                    }
529	                    failure = error;
530	                }
531	            }
532	        }
533	        Err(failure)
534	    }
