670	// Context readiness survives an output-discovery failure. Consumers must gate
671	// output work on the explicit plan; the separate failure remains observable.
672	fn prepared_events(device: u64, info: GpuInfo) -> Vec<NativeEvent> {
673	    let failure = info.output_failure;
674	    let mut events = vec![NativeEvent::GpuReady(info)];
675	    if let Some(error) = failure {
676	        events.push(NativeEvent::Failure {
677	            device: Some(device),
678	            error,
679	        });
680	    }
681	    events
682	}
683	// Closed admission suppresses ready/input events, while terminal diagnostics
684	// and the final inactive transition remain observable, including after failure.
685	fn dispatch_events(
686	    events: impl IntoIterator<Item = NativeEvent>,
687	    mut notify: impl FnMut(NativeEvent),
688	    live: impl Fn() -> bool,
689	) {
690	    for event in events {
691	        if live()
692	            || matches!(
693	                event,
694	                NativeEvent::Failure { .. } | NativeEvent::SessionActive(false)
695	            )
696	        {
697	            notify(event);
698	        }
