            match scanout::Output::begin(
                &mut context,
                assignment.clone(),
                format,
                gpu.output_epoch,
                color,
            ) {
                Ok(output) => {
                    let info = output.info();
                    gpu.output = Some(output);
                    return Ok(info);
                }
                Err(error) => {
                    if !matches!(error.stage, PreviewStage::Prepare | PreviewStage::Test) {
                        return Err(error);
                    }
                    failure = error;
                }
            }
        }
