20	const MAX_CURSOR_SURFACES: usize = 64;
21	const MAX_CURSOR_DEPTH: usize = 32;
22	
23	fn origin(
24	    pointer: Point<f64, Logical>,
25	    hotspot: Point<i32, Logical>,
26	) -> Option<Point<i32, Physical>> {
27	    if !pointer.x.is_finite() || !pointer.y.is_finite() {
28	        return None;
29	    }
30	    let x = pointer.x.round() - f64::from(hotspot.x);
31	    let y = pointer.y.round() - f64::from(hotspot.y);
32	    if x < f64::from(i32::MIN)
33	        || y < f64::from(i32::MIN)
34	        || x > f64::from(i32::MAX - 32)
35	        || y > f64::from(i32::MAX - 32)
36	        || x.abs() > 1_048_576.
37	        || y.abs() > 1_048_576.
38	    {
39	        return None;
40	    }
41	    Some((x as i32, y as i32).into())
42	}
43	
44	pub fn paint(
45	    renderer: &mut GlesRenderer,
46	    target: &mut GlesTarget<'_>,
47	    size: Size<i32, Physical>,
48	    status: &CursorImageStatus,
49	    pointer: Point<f64, Logical>,
50	) -> Result<Option<SyncPoint>, String> {
51	    if matches!(status, CursorImageStatus::Hidden) {
52	        return Ok(None);
53	    }
54	    let bounds = Rectangle::from_size(size);
55	    let mut elements: Vec<CropRenderElement<WaylandSurfaceRenderElement<GlesRenderer>>> =
56	        Vec::new();
57	    let hotspot = if let CursorImageStatus::Surface(surface) = status {
58	        if !surface.alive() {
59	            return Ok(None);
60	        }
61	        // Bound the tree before invoking Smithay's surface import traversal.
62	        let visited = Cell::new(0usize);
63	        let pixels = Cell::new(0u64);
64	        let over_budget = Cell::new(false);
65	        with_surface_tree_downward(
66	            surface,
67	            0usize,
68	            |_, states, depth| {
69	                visited.set(visited.get() + 1);
70	                if visited.get() > MAX_CURSOR_SURFACES || *depth >= MAX_CURSOR_DEPTH {
71	                    over_budget.set(true);
72	                    return TraversalAction::Break;
73	                }
74	                let Some(data) = states.data_map.get::<RendererSurfaceStateUserData>() else {
75	                    return TraversalAction::SkipChildren;
76	                };
77	                let data = data.lock().unwrap();
78	                let Some(view) = data.view() else {
79	                    return TraversalAction::SkipChildren;
80	                };
81	                let dimensions = data.buffer().and_then(|buffer| buffer_dimensions(buffer));
82	                let oversized = dimensions.is_none_or(|size| {
83	                    size.w <= 0 || size.h <= 0 || size.w > 1024 || size.h > 1024
84	                });
85	                if let Some(dimensions) = dimensions {
86	                    pixels.set(
87	                        pixels.get()
88	                            + u64::from(dimensions.w.max(0) as u32)
89	                                * u64::from(dimensions.h.max(0) as u32),
90	                    );
91	                }
92	                if oversized
93	                    || pixels.get() > 4_194_304
94	                    || view.dst.w > 1024
95	                    || view.dst.h > 1024
96	                    || view.offset.x.unsigned_abs() > 16_384
