102	struct State {
103	    queue: FrameQueue<OwnedTarget, Scene>,
104	    rollback: RestoreState,
105	    fd: DrmDeviceFd,
106	    assignment: Assignment,
107	    format: Format,
108	    key: OutputKey,
109	    last_failure: Option<PreviewFailure>,
110	    rollback_completed: bool,
111	    armed: bool,
112	    // Pin broker originals until all cloned framebuffer/DRM owners have retired.
113	    _seat: Rc<SeatDevice<LibSeatSession>>,
114	}
115	pub(super) struct Output {
116	    state: Option<Box<State>>,
117	}
118	fn color(value: [u8; 4]) -> [f32; 4] {
119	    value.map(|channel| f32::from(channel) / 255.)
120	}
121	fn bytes(a: &Assignment) -> Result<u64, PreviewFailure> {
122	    let pixels = u64::from(a.mode.width) * u64::from(a.mode.height);
123	    if a.mode.width == 0
124	        || a.mode.height == 0
125	        || a.mode.width > crate::target::MAX_TEST_DIMENSION
126	        || a.mode.height > crate::target::MAX_TEST_DIMENSION
127	        || pixels > crate::target::MAX_TEST_PIXELS
128	    {
129	        return Err(PreviewFailure::at(PreviewStage::Admission));
130	    }
131	    Ok(pixels * 4)
132	}
133	impl Output {
134	    pub fn begin(
135	        ctx: &mut Context<'_>,
136	        a: Assignment,
137	        format: Format,
138	        epoch: u64,
139	        value: [u8; 4],
140	    ) -> Result<Self, PreviewFailure> {
141	        let key = OutputKey::new(ctx.ticket, a.crtc, epoch)
142	            .map_err(|_| PreviewFailure::at(PreviewStage::Admission))?;
143	        let mut queue = ctx
144	            .pool
145	            .output(key)
146	            .map_err(|_| PreviewFailure::at(PreviewStage::Admission))?;
147	        let mut request = None;
148	        let mut rollback = None;
149	        let frame = ctx
150	            .pool
151	            .prepare(bytes(&a)?, || {
152	                let (target, initial) = target_test::prepare_live(
153	                    ctx.drm,
154	                    ctx.gbm,
155	                    ctx.renderer,
156	                    ctx.modes,
157	                    &a,
158	                    format,
159	                    color(value),
160	                )
161	                .map_err(|e| PreviewFailure {
162	                    stage: PreviewStage::Prepare,
163	                    errno: e.errno,
164	                })?;
165	                let saved = RestoreState::capture(ctx.drm, &initial)
166	                    .map_err(|e| PreviewFailure::io(PreviewStage::Capture, e))?;
167	                // Both the new configuration AND rollback must pass preflight.
168	                initial
169	                    .test_only(ctx.drm.as_fd())
170	                    .map_err(|e| PreviewFailure::io(PreviewStage::Test, e))?;
171	                saved
172	                    .request()
173	                    .test_only(ctx.drm.as_fd())
174	                    .map_err(|e| PreviewFailure::io(PreviewStage::Test, e))?;
175	                request = Some(initial);
176	                rollback = Some(saved);
177	                Ok((
178	                    OwnedTarget {
179	                        target,
180	                        _seat: ctx.seat.clone(),
181	                    },
182	                    Scene::Color(value),
183	                ))
184	            })
185	            .map_err(|e| match e {
186	                frames::PreparationError::Backend(e) => e,
187	                _ => PreviewFailure::at(PreviewStage::Admission),
188	            });
189	        let frame = match frame {
190	            Ok(frame) => frame,
191	            Err(error) => {
192	                ctx.renderer
193	                    .cleanup_texture_cache()
194	                    .map_err(|_| PreviewFailure::at(PreviewStage::Cleanup))?;
195	                return Err(error);
196	            }
197	        };
198	        let initial = request.expect("prepared initial request");
199	        let result = queue.submit(frame, |_, _| {
200	            match initial.apply_blocking(ctx.drm.as_fd()) {
201	                Ok(()) => SubmitOutcome::Accepted,
202	                // Never infer that an ioctl error proves no consumer exists.
203	                Err(error) => {
204	                    SubmitOutcome::Uncertain(PreviewFailure::io(PreviewStage::Submit, error))
205	                }
206	            }
207	        });
208	        let last_failure = match result {
209	            Ok(cookie) => {
210	                // SAFETY: the initial ALLOW_MODESET ioctl returned synchronously
211	                // without NONBLOCK or events; no previous queue consumer exists.
212	                unsafe {
213	                    queue.complete_blocking(cookie);
214	                }
215	                None
216	            }
217	            Err(SubmitError::Uncertain(error)) => Some(error),
218	            Err(error) => {
219	                drop(error);
220	                ctx.renderer
221	                    .cleanup_texture_cache()
222	                    .map_err(|_| PreviewFailure::at(PreviewStage::Cleanup))?;
223	                return Err(PreviewFailure::at(PreviewStage::Admission));
224	            }
225	        };
226	        Ok(Self {
227	            state: Some(Box::new(State {
228	                queue,
229	                rollback: rollback.expect("prepared rollback"),
230	                fd: ctx.drm.device_fd().clone(),
231	                assignment: a,
232	                format,
233	                key,
234	                last_failure,
235	                rollback_completed: false,
236	                armed: true,
237	                _seat: ctx.seat.clone(),
238	            })),
239	        })
240	    }
241	    pub fn info(&self) -> PreviewInfo {
242	        let s = self.state.as_ref().expect("live output owned");
243	        PreviewInfo {
244	            connector: s.assignment.connector,
245	            queue: s.queue.snapshot(),
246	            visible_color: s.queue.visible_scene().and_then(|scene| match scene {
247	                Scene::Color(color) => Some(*color),
248	                Scene::Content(_) => None,
249	            }),
250	            last_failure: s.last_failure,
251	            rollback_completed: s.rollback_completed,
252	            rollback_cleanup_errors: s.rollback.cleanup_errors(),
253	        }
254	    }
255	    pub fn complete(&mut self, ticket: Ticket, event: crate::drm_events::Flip) {
256	        let s = self.state.as_mut().expect("live output owned");
257	        if s.queue.complete(ticket, event) != frames::Completion::Ignored {
258	            s.last_failure = None;
259	        }
260	    }
261	    pub fn invalidate(&mut self) {
262	        self.state
263	            .as_mut()
264	            .expect("live output owned")
265	            .queue
266	            .invalidate();
267	    }
268	    pub fn content<T: 'static>(&self) -> Option<Rc<T>> {
