271	    pub fn submit(&mut self, ctx: &mut Context<'_>, value: [u8; 4]) -> Result<(), PreviewFailure> {
272	        self.submit_with(ctx, value, |_, _| Ok(Scene::Color(value)))
273	    }
274	    pub fn render<T: 'static>(
275	        &mut self,
276	        ctx: &mut Context<'_>,
277	        compose: impl FnOnce(
278	            &mut GlesRenderer,
279	            &mut GlesTarget<'_>,
280	            Size<i32, Physical>,
281	        ) -> Result<(Rc<T>, SyncPoint), String>,
282	    ) -> Result<(), PreviewFailure> {
283	        self.submit_with(ctx, [0, 0, 0, 255], |renderer, target| {
284	            target
285	                .compose(renderer, compose)
286	                .map(|scene| Scene::Content(scene))
287	                .map_err(|failure| PreviewFailure {
288	                    stage: PreviewStage::Render,
289	                    errno: failure.errno,
290	                })
291	        })
292	    }
293	    fn submit_with(
294	        &mut self,
295	        ctx: &mut Context<'_>,
296	        value: [u8; 4],
297	        compose: impl FnOnce(&mut GlesRenderer, &mut Target) -> Result<Scene, PreviewFailure>,
298	    ) -> Result<(), PreviewFailure> {
299	        let s = self.state.as_mut().expect("live output owned");
300	        let status = s.queue.snapshot();
301	        if !status.active || status.closed || status.faulted || s.rollback_completed {
302	            return Err(PreviewFailure::at(PreviewStage::Inactive));
303	        }
304	        if status.pending_cookie.is_some() {
305	            return Err(PreviewFailure::at(PreviewStage::Busy));
306	        }
307	        let prepared = ctx
308	            .pool
309	            .prepare(bytes(&s.assignment)?, || {
310	                let (mut target, _) = target_test::prepare_live(
311	                    ctx.drm,
312	                    ctx.gbm,
313	                    ctx.renderer,
314	                    ctx.modes,
315	                    &s.assignment,
316	                    s.format,
317	                    color(value),
318	                )
319	                .map_err(|e| PreviewFailure {
320	                    stage: PreviewStage::Prepare,
321	                    errno: e.errno,
322	                })?;
323	                let scene = compose(ctx.renderer, &mut target)?;
324	                Ok((
325	                    OwnedTarget {
326	                        target,
327	                        _seat: ctx.seat.clone(),
328	                    },
329	                    scene,
330	                ))
331	            })
332	            .map_err(|e| match e {
333	                frames::PreparationError::Backend(e) => e,
334	                _ => PreviewFailure::at(PreviewStage::Admission),
335	            });
336	        let prepared = match prepared {
337	            Ok(frame) => frame,
338	            Err(error) => {
339	                ctx.renderer
340	                    .cleanup_texture_cache()
341	                    .map_err(|_| PreviewFailure::at(PreviewStage::Cleanup))?;
342	                return Err(error);
343	            }
344	        };
345	        let result = s.queue.submit(prepared, |cookie, owned| {
346	            let request = match owned.target.flip_request() {
347	                Ok(r) => r,
348	                Err(e) => {
349	                    return SubmitOutcome::Rejected(PreviewFailure {
350	                        stage: PreviewStage::Prepare,
351	                        errno: e.errno,
352	                    });
353	                }
354	            };
355	            match request.submit(ctx.drm.as_fd(), cookie) {
356	                Ok(()) => SubmitOutcome::Accepted,
357	                Err(e) => SubmitOutcome::Uncertain(PreviewFailure::io(PreviewStage::Submit, e)),
358	            }
359	        });
360	        match result {
361	            Ok(_) => Ok(()),
362	            Err(SubmitError::Uncertain(error)) => {
363	                s.last_failure = Some(error);
364	                Err(error)
365	            }
366	            Err(SubmitError::Rejected { error, frame }) => {
367	                drop(frame);
368	                ctx.renderer
369	                    .cleanup_texture_cache()
370	                    .map_err(|_| PreviewFailure::at(PreviewStage::Cleanup))?;
371	                s.last_failure = Some(error);
372	                Err(error)
373	            }
374	            Err(error) => {
375	                drop(error);
376	                ctx.renderer
