178	fn parse_native_output(value: &str) -> Result<(u64, u32), Box<dyn std::error::Error>> {
179	    let (device, connector) = value
180	        .split_once(':')
181	        .ok_or("native output must be DEVICE:CONNECTOR decimal IDs")?;
182	    if device.is_empty()
183	        || connector.is_empty()
184	        || !device
185	            .bytes()
186	            .chain(connector.bytes())
187	            .all(|c| c.is_ascii_digit())
188	    {
189	        return Err("native output must contain decimal device and connector IDs".into());
190	    }
191	    let device = device.parse()?;
192	    let connector = connector.parse()?;
193	    if connector == 0 {
194	        return Err("connector ID must be nonzero".into());
195	    }
196	    Ok((device, connector))
197	}
