199	    if options.backend.as_deref() == Some("native") {
200	        if !cfg!(feature = "native") {
201	            return Err("native backend requires a build with --features native".into());
202	        }
203	        if options.native_output.is_none() {
204	            return Err("native backend requires --native-output DEVICE:CONNECTOR".into());
205	        }
