215	fn absolute_config_path(path: PathBuf) -> std::io::Result<PathBuf> {
216	    use std::os::unix::ffi::OsStrExt;
217	    let valid = |p: &std::path::Path| {
218	        let bytes = p.as_os_str().as_bytes();
219	        !bytes.is_empty()
220	            && bytes.len() <= flux_config::MAX_SOURCE_PATH_BYTES
221	            && !bytes.contains(&0)
222	    };
223	    if !valid(&path) {
224	        return Err(std::io::Error::new(
225	            std::io::ErrorKind::InvalidInput,
226	            "configuration paths must contain 1..4096 NUL-free bytes",
227	        ));
228	    }
229	    let path = std::path::absolute(path)?;
230	    if !valid(&path) {
231	        return Err(std::io::Error::new(
232	            std::io::ErrorKind::InvalidInput,
233	            "absolute configuration path exceeds 4096 bytes",
234	        ));
235	    }
236	    Ok(path)
237	}
238	fn config_source(
239	    explicit: Option<PathBuf>,
240	    disabled: bool,
241	    xdg: Option<OsString>,
242	    home: Option<OsString>,
243	) -> std::io::Result<Option<PathBuf>> {
244	    if disabled {
245	        return Ok(None);
246	    }
247	    explicit
248	        .or_else(|| {
249	            xdg.filter(|v| !v.is_empty())
250	                .map(PathBuf::from)
251	                .filter(|p| p.is_absolute())
252	                .or_else(|| {
253	                    home.map(|p| PathBuf::from(p).join(".config"))
254	                        .filter(|p| p.is_absolute())
255	                })
256	                .map(|p| p.join("fluxwm/config.lua"))
257	        })
258	        .map(absolute_config_path)
259	        .transpose()
260	}
