275	fn write_json_new(
276	    path: &std::path::Path,
277	    value: &impl serde::Serialize,
278	) -> Result<(), Box<dyn std::error::Error>> {
279	    use std::io::Write;
280	    let parent = path
281	        .parent()
282	        .filter(|p| !p.as_os_str().is_empty())
283	        .unwrap_or(std::path::Path::new("."));
284	    let mut file = tempfile::NamedTempFile::new_in(parent)?;
285	    serde_json::to_writer_pretty(&mut file, value)?;
286	    file.write_all(b"\n")?;
287	    file.flush()?;
288	    // Publish a complete file atomically without replacing an existing path.
289	    file.persist_noclobber(path)?;
290	    Ok(())
291	}
