293	pub(crate) fn spawn_client(
294	    command: &std::ffi::OsStr,
295	    args: &[OsString],
296	    socket: &std::ffi::OsStr,
297	    ipc: Option<&std::path::Path>,
298	) -> std::io::Result<Child> {
299	    use std::os::unix::process::CommandExt;
300	    let mut command = Command::new(command);
301	    command
302	        .args(args)
303	        .env("WAYLAND_DISPLAY", socket)
304	        .env_remove("WAYLAND_SOCKET")
305	        .env_remove("DISPLAY");
306	    if let Some(path) = ipc {
307	        command.env("FLUXWM_SOCKET", path);
308	    } else {
309	        command.env_remove("FLUXWM_SOCKET");
310	    }
311	    // SAFETY: child-only closure uses async-signal-safe signal-mask operations,
312	    // with no allocator/locks. Undo only masks installed by this executable.
313	    unsafe {
314	        command.pre_exec(|| {
